            cacheOnly: true, repository: 'o/r'
        } } });
        assert.equal(res.success, true);
        assert.equal(res.tokens, undefined, 'no tokens key when the knob is off');
        assert.equal(execCalls.length, 0, 'zero gh traffic without the knob');
    });
});

