    function stubGhPut(state, map) {
        state.puts += 1;
        if (state.puts <= (map.failPuts || 0)) {
            state.failed += 1;
            throw new Error('gh: 409 sha was not supplied');
        }
        return { output: '' };
    }

    function stubGhSha(map) {
        if (map.sha == null) throw new Error('gh: Not Found (404)');
        return { output: map.sha };
